protocol Component { func update(_ entity: inout Entity, _ dt: Double) }

struct Entity {
    var transform = Transform()
    var parts: [any Component] = []

    mutating func update(_ dt: Double) {
        for p in parts { p.update(&self, dt) }
    }
}

